{"explanation":"The tangent function, tan(x) = sin(x)/cos(x), repeats every π. Vertical asymptotes occur where cos(x) = 0: x = π/2 + kπ, so the interval [−2π, 2π] contains four asymptotes at −3π/2, −π/2, π/2, and 3π/2. At each asymptote, tan(x) approaches +∞ from the left and −∞ from the right; the function is undefined on the asymptote itself. Use the slider to explore the central branch.","manimCode":"const ax = new Axes({
  xRange: [-2 * Math.PI, 2 * Math.PI, Math.PI / 2],
  yRange: [-3.5, 3.5, 1],
  xLength: 10.8,
  yLength: 4.6,
  tips: false
});
ax.moveTo([0, -0.15, 0]);

const heading = new MathTex({ latex: 'y=\\tan(x)=\\frac{\\sin(x)}{\\cos(x)}', color: BLUE });
await heading.waitForRender();
heading.scale(0.85);
heading.moveTo([-2.3, 3.05, 0]);
scene.add(heading);
await scene.play(new Create(ax));

const polePositions = [-3 * Math.PI / 2, -Math.PI / 2, Math.PI / 2, 3 * Math.PI / 2];
const dashedLines = new VGroup();
for (const pole of polePositions) {
  for (let yy = -3.5; yy < 3.5; yy += 0.36) {
    const dash = new Line({
      start: ax.coordsToPoint(pole, yy),
      end: ax.coordsToPoint(pole, Math.min(yy + 0.19, 3.5)),
      color: RED
    });
    dash.setStrokeWidth(2);
    dash.setOpacity(0.75);
    dashedLines.add(dash);
  }
}
await scene.play(new FadeIn(dashedLines));

const branches = new VGroup();
const limit = Math.atan(3.5);
for (let k = -2; k <= 2; k++) {
  const leftEdge = Math.max(-2 * Math.PI, k * Math.PI - limit);
  const rightEdge = Math.min(2 * Math.PI, k * Math.PI + limit);
  const branch = ax.plot(x => Math.tan(x), {
    xRange: [leftEdge, rightEdge],
    color: BLUE,
    numSamples: 180
  });
  branch.setStrokeWidth(3);
  branches.add(branch);
}
await scene.play(new Create(branches));

const tickSpecs = [
  [-2 * Math.PI, '-2\\pi'],
  [-Math.PI, '-\\pi'],
  [0, '0'],
  [Math.PI, '\\pi'],
  [2 * Math.PI, '2\\pi']
];
for (const [xx, latex] of tickSpecs) {
  const tickLabel = new MathTex({ latex, color: GRAY });
  await tickLabel.waitForRender();
  tickLabel.scale(0.55);
  tickLabel.moveTo(ax.coordsToPoint(xx, 0));
  tickLabel.shift([0, -0.3, 0]);
  scene.add(tickLabel);
}

