asymptoteFormula.scale(0.7);
asymptoteFormula.moveTo([0, -2.95, 0]);
await scene.play(new Write(asymptoteFormula));

const note = new Text({
  text: 'Dashed red lines: undefined values, not part of the graph',
  fontSize: 20,
  color: GRAY
});
note.moveTo([0, -3.45, 0]);
scene.add(note);

const marker = new Dot({ point: ax.coordsToPoint(0, 0), color: YELLOW });
scene.add(marker);
makeHoverable(marker, scene, { hoverScale: 1.4 });
